insert into "founder_stages" ("stage_id", "created_at", "criteria_version", "description", "key_characteristics", "max_criteria", "min_criteria", "onboarding_label", "question_budget", "stage_name", "stage_order", "top_operational_problems", "top_psychological_challenges", "updated_at") values ('1', '2026-07-10 11:21:06.93641+00', '1', 'Idea and problem concept stage. No product yet. Everything is possibility and uncertainty. The founder is defining the problem, hypothesising solutions, and taking their first steps toward building.', '["Founders define the problem and hypothesise solutions", "Market research and customer interviews begin", "No working product or prototype — just plans and ideas", "Typically bootstrapped or very small funding", "High uncertainty and openness to pivot"]', '{"revenue": 0, "has_prototype": false, "paying_customers": 0, "customer_interviews_max": 10}', '{"has_idea": true, "funding_stage": "none", "has_prototype": false, "team_size_min": 1, "customer_interviews_min": 0}', 'Stage 0', '14', 'Ideation', '1', '["Lack of clarity on problem and solution definition", "Limited resources and no budget to speak of", "Analysis paralysis — overthinking before acting", "Recruiting co-founders or building an initial team", "No tangible progress to show to stakeholders or supporters"]', '["Imposter syndrome and deep self-doubt", "Decision paralysis driven by uncertainty", "Loneliness and isolation — building alone", "Fear of taking the first concrete step", "Overwhelm and anxiety about failure before starting"]', '2026-09-04 15:07:38.777962+00') on conflict do nothing;
insert into "founder_stages" ("stage_id", "created_at", "criteria_version", "description", "key_characteristics", "max_criteria", "min_criteria", "onboarding_label", "question_budget", "stage_name", "stage_order", "top_operational_problems", "top_psychological_challenges", "updated_at") values ('2', '2026-07-10 11:21:06.93641+00', '1', 'Concept testing stage. Prototypes or mockups tested to validate problem and solution fit. The founder is actively seeking evidence that the idea is worth building before committing fully.', '["Basic prototype or mockups developed", "Active customer feedback via interviews or surveys", "Business model hypotheses defined and refined", "Initial legal and team structure formalised", "Often seeking seed or pre-seed funding from angels or accelerators"]', '{"revenue": 0, "paying_customers": 0, "pilot_signups_or_loi_max": 5}', '{"funding_stage": "pre-seed or none", "has_prototype": true, "paying_customers": 0, "customer_interviews_min": 10}', 'Stage 0→1', '20', 'Validation', '2', '["Pivoting direction based on conflicting customer feedback", "Prioritising features versus lean testing speed", "Limited budget to iterate and test quickly", "Undefined go-to-market strategy", "Building trust with first potential customers who do not know you"]', '["Fear of rejection from early customer feedback", "Pressure to commit to a specific direction", "Maintaining confidence while receiving criticism", "Stress of handling uncertain and sometimes contradictory results", "Feeling accountable for early team members who have joined"]', '2026-09-04 15:07:38.777962+00') on conflict do nothing;
insert into "founder_stages" ("stage_id", "created_at", "criteria_version", "description", "key_characteristics", "max_criteria", "min_criteria", "onboarding_label", "question_budget", "stage_name", "stage_order", "top_operational_problems", "top_psychological_challenges", "updated_at") values ('3', '2026-07-10 11:21:06.93641+00', '1', 'Product development stage. Minimum viable product built and tested with early adopter users. The founder is searching for product-market fit signals and iterating rapidly based on real usage.', '["MVP or first working prototype launched", "Early adopter customers engaged as beta users", "Focus on product-market fit signals and early retention", "Iteration cycles are frequent — build, measure, learn", "Securing initial users and seed funding"]', '{"mrr_max": 1000, "customers_max": 10, "paying_customers_max": 10}', '{"has_mvp": true, "funding_stage": "seed or none", "active_customers_min": 1, "paying_customers_min": 0}', 'Stage 0→1', '24', 'Prototype / MVP', '3', '["Gathering and actually acting on early user feedback", "Fixing bugs and improving the product rapidly", "Managing very limited resources against feature goals", "Aligning the team''s efforts on core features only", "Balancing product development with early sales outreach"]', '["Anxiety about how first users will receive the product", "Burnout risk from intense and rapid iteration cycles", "Maintaining motivation when initial results are weak", "Self-doubt about technical or product-building ability", "Stress of tight time-to-market deadlines and investor expectations"]', '2026-09-04 15:07:38.777962+00') on conflict do nothing;
insert into "founder_stages" ("stage_id", "created_at", "criteria_version", "description", "key_characteristics", "max_criteria", "min_criteria", "onboarding_label", "question_budget", "stage_name", "stage_order", "top_operational_problems", "top_psychological_challenges", "updated_at") values ('4', '2026-07-10 11:21:06.93641+00', '1', 'Initial market traction. Product has paying customers and revenue growth begins. The founder is transitioning from builder to leader and establishing repeatable processes for the first time.', '["Working product with paying customers", "Evidence of repeat usage or growing monthly recurring revenue", "Defined value proposition and early product-market fit signals", "Team expanded — sales and marketing roles being added", "Building first repeatable sales and onboarding processes"]', '{"mrr_max": 10000, "customers_max": 100}', '{"mrr_min": 1000, "paying_customers_min": 1, "mom_growth_rate_min_pct": 20, "has_repeatable_sales_process": false}', 'Stage 0→1', '30', 'Early Traction', '4', '["Building a scalable and repeatable sales pipeline", "Optimising customer acquisition and early retention", "Hiring to meet growth without overspending", "Managing cash flow as costs rise with growth", "Implementing first real processes and tracking metrics"]', '["Performance anxiety to hit growing investor and self-imposed targets", "Overcommitment and first serious work-life imbalance", "Fear of scaling too fast or plateauing too early", "Adjusting identity from builder and doer to leader and enabler", "Pressure from investor expectations after first fundraise"]', '2026-09-04 15:07:38.777962+00') on conflict do nothing;
insert into "founder_stages" ("stage_id", "created_at", "criteria_version", "description", "key_characteristics", "max_criteria", "min_criteria", "onboarding_label", "question_budget", "stage_name", "stage_order", "top_operational_problems", "top_psychological_challenges", "updated_at") values ('5', '2026-07-10 11:21:06.93641+00', '1', 'Scaling stage. Company expands rapidly with Series A funding and unit economics focus. The founder is managing a real organisation and must transition from doing to leading.', '["Consistent month-over-month growth", "Focus on unit economics — CAC, LTV, churn rates", "Robust sales and marketing channels now established", "Processes and teams formalising into departments with budgets", "Series A investment secured to fuel expansion"]', '{"arr_max": 1000000, "approaching_breakeven": true}', '{"arr_min": 100000, "funding_stage": "Series A", "cac_to_ltv_ratio_min": 1.0, "has_formal_departments": true}', 'Stage 1→10+', '30', 'Growth / Scaling', '5', '["Scaling operations without losing quality or culture", "Optimising unit economics and building toward profitability", "Scaling team and culture rapidly without breaking either", "Managing increasing competition and market shifts", "Ensuring product stability under significantly heavier usage"]', '["Founder burnout from relentless pace and expanding responsibility", "Identity fusion — company performance feels completely personal", "Stress from delegating control to a growing leadership team", "Pressure to justify high post-Series A valuation", "Loneliness as demands on time and energy intensify"]', '2026-09-04 15:07:38.777962+00') on conflict do nothing;
insert into "founder_stages" ("stage_id", "created_at", "criteria_version", "description", "key_characteristics", "max_criteria", "min_criteria", "onboarding_label", "question_budget", "stage_name", "stage_order", "top_operational_problems", "top_psychological_challenges", "updated_at") values ('6', '2026-07-10 11:21:06.93641+00', '1', 'Expansion stage. Company diversifies into new products or markets with Series B or C funding. The founder is managing organisational complexity at a scale that requires entirely new leadership skills.', '["Rapid team growth — often hundreds of employees", "Product-market fit confirmed — entering new markets or geographies", "New product lines or international expansion underway", "Focus on systems to manage organisational complexity", "Series B or C funding secured for aggressive scaling"]', '{"arr_max": 10000000, "international_markets_min": 3}', '{"arr_min": 1000000, "markets_min": 1, "funding_stage": "Series B or C", "churn_rate_max_pct": 5}', 'Stage 1→10+', '32', 'Expansion', '6', '["Maintaining culture and communication quality at significant scale", "Managing bureaucracy and cross-team coordination challenges", "Retaining top talent amid rapid and continuous hiring", "Balancing short-term growth pressure with long-term strategic direction", "Complex financial and legal compliance requirements multiplying"]', '["Decision fatigue from dramatically increased complexity", "Stress of high-stakes performance and potential IPO pressure", "Doubt about sustaining the original vision at scale", "Risk aversion spreading among employees — culture becomes conservative", "Frustration from loss of hands-on product and execution work"]', '2026-09-04 15:07:38.777962+00') on conflict do nothing;
insert into "founder_stages" ("stage_id", "created_at", "criteria_version", "description", "key_characteristics", "max_criteria", "min_criteria", "onboarding_label", "question_budget", "stage_name", "stage_order", "top_operational_problems", "top_psychological_challenges", "updated_at") values ('7', '2026-07-10 11:21:06.93641+00', '1', 'Mature stage. Stable processes, consistent profitability, and preparation for exit or IPO. The founder is now a CEO of a large organisation and their original startup instincts must evolve into institutional leadership.', '["Consistent profitability or a clear and credible path to it", "Professional management and governance structures in place", "Market leadership or dominant share in a specific niche", "Diversified product lines and global presence", "Preparing for exit — IPO readiness or acquisition conversations"]', '{"ipo_ready_or_acquisition_initiated": true}', '{"annual_revenue_min": 10000000, "profit_margin_min_pct": 10, "has_governance_structure": true, "has_professional_management": true}', 'Stage 1→10+', '32', 'Maturity', '7', '["Maintaining innovation within a large and sometimes bureaucratic organisation", "Board and investor governance requirements consuming significant time", "Succession planning and leadership transition preparation", "Compliance with public market or regulatory standards", "Balancing shareholder expectations with company culture and values"]', '["Founder identity crisis after relinquishing day-to-day control", "Loneliness at the top and loss of the mission-driven adrenaline", "Pressure of sustaining growth for investors and public markets", "Golden handcuff depression — financially successful but feeling trapped", "Fear of irrelevance as the organisation no longer needs the founder daily"]', '2026-09-04 15:07:38.777962+00') on conflict do nothing;
insert into "founder_stages" ("stage_id", "created_at", "criteria_version", "description", "key_characteristics", "max_criteria", "min_criteria", "onboarding_label", "question_budget", "stage_name", "stage_order", "top_operational_problems", "top_psychological_challenges", "updated_at") values ('8', '2026-07-10 11:21:06.93641+00', '1', 'Exit stage. Company sold or goes public. Founder transitions out of the startup role. The journey that defined their identity reaches its culmination — and a new chapter begins whether they are ready or not.', '["Exit event — acquisition, merger, or IPO — occurs", "Founder''s role changes to new executive role, adviser, or retirement", "Focus shifts to integration with acquirer or post-exit strategy", "Financial outcomes realised — liquidity for founders and investors", "Company may restart a new growth cycle under new ownership"]', '{"exit_completed": true}', '{"exit_type": "acquisition or merger or IPO", "exit_process_initiated": true}', 'Stage 1→10+', '30', 'Exit', '8', '["Navigating due diligence and deal negotiation process", "Integrating with acquiring company or new board of directors", "Retaining key talent through an uncertain transition period", "Executing the exit strategy — for example the IPO roadshow", "Transitioning company processes and culture to new governance"]', '["Post-exit depression and profound loss of identity", "Grieving the end of the startup journey that defined their life", "Anxiety about what comes next in career and personal life", "Imposter syndrome in a new role without familiar startup challenges", "Decision paralysis about what to do next — purpose vacuum"]', '2026-09-04 15:07:38.777962+00') on conflict do nothing;
